<script lang="ts">
 import PageHeader from '$lib/admin/PageHeader.svelte'; import EmptyState from '$lib/admin/EmptyState.svelte'; import { Button } from '$lib/components/ui/button'; import { Badge } from '$lib/components/ui/badge'; import { Input } from '$lib/components/ui/input'; import { Textarea } from '$lib/components/ui/textarea'; import { Label } from '$lib/components/ui/label'; import * as Dialog from '$lib/components/ui/dialog'; import { Alert, AlertDescription } from '$lib/components/ui/alert'; import { Plus, Pencil, Trash2, FileText } from '@lucide/svelte'; import { enhance } from '$app/forms'; import { invalidateAll } from '$app/navigation'; import { toast } from 'svelte-sonner';
 let {data,form}=$props();let open=$state(false);let editing=$state<any>(null);const done=()=>async({update}:any)=>{await update();await invalidateAll();toast.success('Template tersimpan');open=false;editing=null};
</script>
<PageHeader title="Template surat" description="Standarkan struktur surat dan percepat pembuatan pengajuan."><Button onclick={()=>{editing=null;open=true}} class="bg-blue-500"><Plus/>Template baru</Button></PageHeader>
{#if form?.error}<Alert variant="destructive" class="mb-4"><AlertDescription>{form.error}</AlertDescription></Alert>{/if}
{#if data.templates.length}<div class="grid gap-4 lg:grid-cols-2">{#each data.templates as item}<article class="rounded-xl border bg-card p-5"><div class="flex items-start gap-3"><div class="grid size-10 shrink-0 place-items-center rounded-lg bg-orange-50 text-orange-500"><FileText/></div><div class="min-w-0 flex-1"><div class="flex items-center gap-2"><h2 class="truncate font-serif text-lg font-semibold">{item.name}</h2><Badge variant="secondary">{item.type}</Badge></div><p class="mt-1 truncate text-sm font-medium">{item.subject}</p><p class="mt-2 line-clamp-3 whitespace-pre-wrap text-sm text-muted-foreground">{item.body}</p></div></div><div class="mt-4 flex justify-end gap-1 border-t pt-3"><Button variant="ghost" size="sm" onclick={()=>{editing=item;open=true}}><Pencil/>Edit</Button><form method="POST" action="?/delete" use:enhance={done} onsubmit={(e)=>{if(!confirm('Hapus template ini?'))e.preventDefault()}}><input type="hidden" name="id" value={item.id}/><Button type="submit" variant="ghost" size="sm" class="text-red-700"><Trash2/>Hapus</Button></form></div></article>{/each}</div>{:else}<EmptyState title="Belum ada template" description="Buat template pertama untuk mempercepat pengajuan surat."/>{/if}
<Dialog.Root bind:open><Dialog.Content class="sm:max-w-2xl"><Dialog.Header><Dialog.Title>{editing?'Edit template':'Template baru'}</Dialog.Title><Dialog.Description>Isi dapat diubah lagi ketika dipakai dalam pengajuan.</Dialog.Description></Dialog.Header><form method="POST" action={editing?'?/update':'?/create'} use:enhance={done} class="space-y-4">{#if editing}<input type="hidden" name="id" value={editing.id}/>{/if}<div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><Label for="name">Nama template</Label><Input id="name" name="name" value={editing?.name||''} required/></div><div class="space-y-2"><Label for="type">Jenis surat</Label><Input id="type" name="type" value={editing?.type||''} required/></div><div class="space-y-2 sm:col-span-2"><Label for="subject">Perihal</Label><Input id="subject" name="subject" value={editing?.subject||''} required/></div><div class="space-y-2 sm:col-span-2"><Label for="body">Isi template</Label><Textarea id="body" name="body" rows={12} value={editing?.body||''} required/></div></div><Dialog.Footer><Button type="button" variant="outline" onclick={()=>open=false}>Batal</Button><Button type="submit" class="bg-blue-500">Simpan</Button></Dialog.Footer></form></Dialog.Content></Dialog.Root>
